import { pack, unpack } from "msgpackr";
import { bytesToHex, hexToBytes } from "../Buffer.js";
/**
 * Evolu serializes {@link SqliteQuery} into a string to be easily used as a key
 * and for comparison.
 */
export const serializeQuery = (query) => {
    if (!Array.isArray(query.parameters)) {
        throw new Error("Record params are for internal usage");
    }
    return bytesToHex(pack(query));
};
export const deserializeQuery = (query) => unpack(hexToBytes(query));
// To preserve identity.
export const emptyRows = [];
/**
 * SQLite stores JSON as a string, and it's impossible to parse them
 * automatically without heuristics. Kysely ParseJSONResultsPlugin can creates
 * type-safety issues. Evolu prefers explicit parsing via this helper.
 */
export const parseJsonColumns = (rows, ...keys) => {
    for (const row of rows) {
        for (const key of keys) {
            const value = row[key];
            if (typeof value === "string") {
                // We don't need to try/catch here because we can rely on types.
                // @ts-expect-error Mutate immutable value is OK here because
                // it's done only once. Note `typeof value === "string"`.
                row[key] = JSON.parse(row[key]);
            }
        }
    }
};
export const createQueryRowsCache = () => {
    let queryRowsCache = new Map();
    const cache = {
        set: (queriesRows) => {
            queryRowsCache = new Map([...queryRowsCache, ...queriesRows]);
        },
        get: () => queryRowsCache,
    };
    return cache;
};
export const createSubscribedQueries = (rowsStore) => {
    const subscribedQueryMap = new Map();
    const subscribedQueries = {
        subscribe: (query) => (listener) => {
            subscribedQueryMap.set(query, (subscribedQueryMap.get(query) ?? 0) + 1);
            const unsubscribe = rowsStore.subscribe(listener);
            return () => {
                const count = subscribedQueryMap.get(query);
                if (count != null && count > 1) {
                    subscribedQueryMap.set(query, count - 1);
                }
                else {
                    subscribedQueryMap.delete(query);
                }
                unsubscribe();
            };
        },
        get: () => [...subscribedQueryMap.keys()],
        has: (query) => subscribedQueryMap.has(query),
    };
    return subscribedQueries;
};
