import { kysely } from '@evolu/common';
import type { DataSourceId, NodeId, SettingId } from "./datastructure";
import { type InferRow } from '@evolu/common/evolu';
import { evolu } from './evolu_instance';
import { type Expression } from 'kysely';

export function getNodesQuery(options?: {
	parentId?: NodeId | null;
	type?: string;
	id?: NodeId;
}) {
	const { parentId, id, type } = options ?? {};

	return evolu.createQuery((db) =>
		db
			.selectFrom('nodes')
			.selectAll()
			.$if(!!parentId, (qb) => qb.where('parentId', '==', parentId!))
			.$if(parentId === null, (qb) => qb.where('parentId', 'is', null))
			.$if(!!id, (qb) => qb.where('id', '==', id!))
			.$if(!!type, (qb) => qb.where('type', '==', type!))

			.where('type', 'is not', null)
			.where('isDeleted', 'is', null)
			.$narrowType<{ type: kysely.NotNull }>()
	);
}

export type NodeQueryEntry = InferRow<ReturnType<typeof getNodesQuery>>;


export function getNodeList() {

	return evolu.createQuery((db) =>
		db
			.selectFrom('nodes')
			.select(({ fn, val, ref }) => [
				'id',
				'type',
				'order',
				'parentId',

				fn<string>('json_extract', ['layoutData', val('$.label')]).as('label')
			])
			.where('type', 'is not', null)
			.where('isDeleted', 'is', null)
			.$narrowType<{ type: kysely.NotNull }>()
	);
}

export type NodeListEntry = InferRow<ReturnType<typeof getNodeList>>;


export function getNodeDataByNodeIdListQuery(nodeIdList: NodeId[]) {
	return evolu.createQuery((db) =>
		db
			.selectFrom('nodeData')
			.selectAll()
			.where('nodeId', 'in', nodeIdList)
			.where('isDeleted', 'is', null)
			.$narrowType<{ type: kysely.NotNull }>()
	);
}

export type NodeDataQueryByNodeIdListEntry = InferRow<
	ReturnType<typeof getNodeDataByNodeIdListQuery>
>;

export function getNodeDataByIdPairQuery(nodeId: NodeId, subId: string) {
	return evolu.createQuery((db) =>
		db
			.selectFrom('nodeData')
			.selectAll()
			.where('nodeId', '=', nodeId)
			.where('subId', '=', subId)
			.where('isDeleted', 'is', null)
			.$narrowType<{ type: kysely.NotNull }>()
	);
}

export type NodeDataQueryByIdPairEntry = InferRow<ReturnType<typeof getNodeDataByIdPairQuery>>;

function jsonExtract(col: Expression<unknown>, path: string) {
	return kysely.sql<string>`json_extract(${col}, ${path})`;
}

function whereJsonExtractSelectColumn(col: string) {
	return kysely.sql`${col}`;
}

export function getRootNodeQuery() {
	return evolu.createQuery((db) =>
		db
			.selectFrom('nodes')
			.select(({ fn, val, ref }) => [
				'id',

				fn<string>('json_extract', ['specialFlags', val('$.isRootNode')]).as('isRootNode')
			])
			.where('type', 'is not', null)
			.where('isDeleted', 'is not', 1)
			// @ts-expect-error isRootNode is not recognized as a column
			.where('isRootNode', '==', 1)

			.$narrowType<{ type: kysely.NotNull }>()
	);
}

export function getChildNodesWithDataQuery(options?: { parentId?: NodeId | null; id?: NodeId }) {
	const { parentId, id } = options ?? {};

	return evolu.createQuery((db) =>
		db
			.selectFrom('nodes as n')
			.innerJoin('nodeData as d', 'n.id', 'd.id')
			.selectAll()
			.$if(!!parentId, (qb) => qb.where('parentId', '==', parentId!))
			.$if(parentId === null, (qb) => qb.where('parentId', 'is', null))
			.$if(!!id, (qb) => qb.where('id', '==', id!))
			/*
            .where(({ eb, ref }) => eb(
          jsonExtract(ref('d.data'), '$.isRootNode'), '==', 'true'
        ))*/
			.where('type', 'is not', null)
			.where('isDeleted', 'is', 0)
			.$narrowType<{ type: kysely.NotNull }>()
	);
}

export function getDataSourcesQuery(options?: { short?: string; id?: DataSourceId }) {
	const { id, short } = options ?? {};

	return evolu.createQuery((db) =>
		db
			.selectFrom('dataSources')
			.selectAll()
			.where('isDeleted', 'is', null)
			.$if(!!id, (qb) => qb.where('id', '==', id!))
			.$if(!!short, (qb) =>
				qb.where(({ eb, ref }) => eb(jsonExtract(ref('config'), '$.short'), '==', short!))
			)
			.$narrowType<{ type: kysely.NotNull }>()
	);
}

export type AllDataSourcesQueryEntry = InferRow<ReturnType<typeof getDataSourcesQuery>>;

export function getSettingsQuery(options?: {
	id?: SettingId,
	byKey?: string
}) {
	const { byKey, id } = options ?? {};

	return evolu.createQuery((db) =>
		db
			.selectFrom('settings')
			.selectAll()
			.where('isDeleted', 'is', null)
			.$if(!!byKey, (qb) => qb.where('key', '==', byKey!))
			.$if(!!id, (qb) => qb.where('id', '==', id!))
			.$narrowType<{ type: kysely.NotNull }>()
	);
}

export type AllSettingsQueryEntry = InferRow<ReturnType<typeof getSettingsQuery>>;
